#!/usr/bin/env node
// Builds tracegrid.dev into site/dist: the landing page, its images, and /demo (graph.html of the
// bundled demo app, generated by this checkout). Cloudflare Pages: build command
// `node site/build.mjs`, output directory `site/dist`.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dist = path.join(repo, 'site/dist');
fs.rmSync(dist, { recursive: true, force: true });
fs.mkdirSync(path.join(dist, 'demo'), { recursive: true });

fs.copyFileSync(path.join(repo, 'site/index.html'), path.join(dist, 'index.html'));
fs.copyFileSync(path.join(repo, 'site/_headers'), path.join(dist, '_headers'));
for (const f of ['tracegrid.gif', 'dashboard.png']) fs.copyFileSync(path.join(repo, 'docs', f), path.join(dist, f));

// --demo exits 0 whatever it finds (no --check); anything else is a real failure.
const out = path.join(dist, 'demo');
execFileSync(process.execPath, [path.join(repo, 'bin/tracegrid.js'), '--demo', '--out', out], { stdio: ['ignore', 'ignore', 'inherit'] });
fs.renameSync(path.join(out, 'graph.html'), path.join(out, 'index.html'));
for (const f of ['index.html', 'graph.json', 'report.md']) if (!fs.existsSync(path.join(out, f))) throw new Error(`demo did not write ${f}`);
// /demo/firebase: the Firebase + Flutter example.
const fbOut = path.join(dist, 'demo', 'firebase');
execFileSync(process.execPath, [path.join(repo, 'bin/tracegrid.js'), '--demo', 'firebase', '--out', fbOut], { stdio: ['ignore', 'ignore', 'inherit'] });
fs.renameSync(path.join(fbOut, 'graph.html'), path.join(fbOut, 'index.html'));
console.log(`site built: ${path.relative(repo, dist)}`);
